/** Structural view of a markup node; lint (source tags) and Studio (DOM) adapt to it. */
type StructureNode<N = unknown> = {
    tag: string;
    attrs: Readonly<Record<string, string | undefined>>;
    children: readonly N[];
};
type TrackKind = "video" | "audio" | "captions" | "graphics";
type TrackKindSource = "attribute" | "tag" | "legacy-captions" | "sub-composition";
declare function isSubCompositionHost(node: StructureNode): boolean;
/** Mirrors the runtime's clip selector; a data-track-index layer container without a duration is not a clip. */
declare function isTimedElement(node: StructureNode): boolean;
/**
 * The elements that own a timeline row: a sub-composition host or timed element is one row
 * and is never descended into; untimed wrappers are descended. The root itself is not a row.
 */
declare function topLevelElements<N extends StructureNode<N>>(root: N): N[];
declare function trackKindOf(node: StructureNode): {
    kind: TrackKind;
    source: TrackKindSource;
};

export { type StructureNode, type TrackKind, type TrackKindSource, isSubCompositionHost, isTimedElement, topLevelElements, trackKindOf };
